def token_required(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('Authorization')
        if not token:
            return jsonify({'message': 'Token is missing'}), 401
        try:
            data = jwt.decode(token.split()[1], app.config['SECRET_KEY'], algorithms=['HS256'])
            current_user = data['user_id']
        except:
            return jsonify({'message': 'Token is invalid'}), 401
        return f(current_user, *args, **kwargs)
    return decorated

@app.route('/register', methods=['POST'])
def register():
    data = request.json
    username = data['username']
    email = data['email']
    password = data['password']
    hashed = bcrypt.hashpw(password.encode('utf-8'), bcrypt.gensalt())
    cursor.execute('INSERT INTO users (username, email, password_hash) VALUES (?, ?, ?)', (username, email, hashed))
    db.commit()
    user_id = cursor.lastrowid
    cursor.execute('INSERT INTO billing (user_id) VALUES (?)', (user_id,))
    db.commit()
    token = jwt.encode({'user_id': user_id, 'exp': datetime.utcnow() + timedelta(hours=24)}, app.config['SECRET_KEY'])
    return jsonify({'token': token})

@app.route('/login', methods=['POST'])
def login():
    data = request.json
    email = data['email']
    password = data['password']
    cursor.execute('SELECT * FROM users WHERE email = ?', (email,))
    user = cursor.fetchone()
    if user and bcrypt.checkpw(password.encode('utf-8'), user[3]):
        token = jwt.encode({'user_id': user[0], 'exp': datetime.utcnow() + timedelta(hours=24)}, app.config['SECRET_KEY'])
        return jsonify({'token': token})
    return jsonify({'message': 'Invalid credentials'}), 401

@app.route('/sso', methods=['POST'])
def sso():
    data = request.json
    email = data.get('email')
    if email:
        cursor.execute('SELECT * FROM users WHERE email = ?', (email,))
        user = cursor.fetchone()
        if user:
            token = jwt.encode({'user_id': user[0], 'exp': datetime.utcnow() + timedelta(hours=24)}, app.config['SECRET_KEY'])
            return jsonify({'token': token})
        else:
            username = email.split('@')[0]
            hashed = bcrypt.hashpw('sso_pass'.encode('utf-8'), bcrypt.gensalt())
            cursor.execute('INSERT INTO users (username, email, password_hash, plan_type) VALUES (?, ?, ?, ?)', (username, email, hashed, 'enterprise'))
            db.commit()
            user_id = cursor.lastrowid
            cursor.execute('INSERT INTO billing (user_id) VALUES (?)', (user_id,))
            db.commit()
            token = jwt.encode({'user_id': user_id, 'exp': datetime.utcnow() + timedelta(hours=24)}, app.config['SECRET_KEY'])
            return jsonify({'token': token})
    return jsonify({'message': 'Invalid SSO data'}), 400

