@app.route('/import', methods=['POST'])
@token_required
def import_project(current_user):
    data = request.json
    source = data['source']
    files = {}
    if source.endswith('.zip'):
        zip_content = requests.get(source).content
        with zipfile.ZipFile(io.BytesIO(zip_content)) as z:
            for f in z.namelist():
                if not f.endswith('/'):
                    files[f] = z.read(f).decode('utf-8')
    name = data.get('name', 'Imported Project')
    cursor.execute('INSERT INTO projects (owner_id, name, files_json) VALUES (?, ?, ?)', (current_user, name, json.dumps(files)))
    db.commit()
    project_id = cursor.lastrowid
    return jsonify({'project_id': project_id})

