@app.route('/storage/<int:project_id>', methods=['POST', 'GET'])
@token_required
def storage_manage(current_user, project_id):
    cursor.execute('SELECT files_json FROM storage WHERE project_id = ?', (project_id,))
    files = json.loads(cursor.fetchone()[0])
    if request.method == 'GET':
        file_name = request.args.get('file')
        if file_name:
            return jsonify({'content': files.get(file_name)})
        return jsonify({'files': list(files.keys())})
    file = request.files['file']
    file_name = secure_filename(file.filename)
    files[file_name] = base64.b64encode(file.read()).decode()
    cursor.execute('UPDATE storage SET files_json = ? WHERE project_id = ?', (json.dumps(files), project_id))
    db.commit()
    return jsonify({'message': 'Uploaded'})

