        return jsonify({'message': 'Insufficient credits'}), 402
    grok_headers = {'Authorization': f'Bearer {xai_api_key}', 'Content-Type': 'application/json'}
    grok_body = {'model': 'grok-4.1-fast', 'messages': [{'role': 'system', 'content': 'You are a fast reasoning AI for planning code tasks.'}, {'role': 'user', 'content': prompt}]}
    grok_response = requests.post('', headers=grok_headers, json=grok_body).json()
    reasoned_prompt = grok_response['choices'][0]['message']['content']
    claude_body = json.dumps({'anthropic_version': 'bedrock-2023-05-31', 'max_tokens': 4096, 'temperature': 0.7, 'messages': [{'role': 'user', 'content': [{'type': 'text', 'text': reasoned_prompt}]}]})
    claude_response = bedrock.invoke_model(modelId='anthropic.claude-opus-4.5-v1:0', body=claude_body)
    claude_output = json.loads(claude_response['body'].read())['content'][0]['text']
    cursor.execute('SELECT files_json, snapshots_json FROM projects WHERE id = ?', (project_id,))
    project = cursor.fetchone()
    files = json.loads(project[0])
    files.update(json.loads(claude_output))
    snapshots = json.loads(project[1])
    snapshots.append({'timestamp': time.time(), 'files': files})
    cursor.execute('UPDATE projects SET files_json = ?, snapshots_json = ? WHERE id = ?', (json.dumps(files), json.dumps(snapshots), project_id))
    cursor.execute('UPDATE users SET credits = credits - 10 WHERE id = ?', (current_user,))
    db.commit()
    return jsonify({'output': claude_output})

