_bedrock_client = None
_bedrock_lock = threading.Lock()

def get_bedrock_client():
    global _bedrock_client
    if _bedrock_client is not None:
        return _bedrock_client
    with _bedrock_lock:
        if _bedrock_client is not None:
            return _bedrock_client
        _bedrock_client = boto3.client("bedrock-runtime", region_name=AWS_REGION)
        return _bedrock_client

def get_db():
    conn = getattr(g, "_db_conn", None)
    if conn is None:
        conn = sqlite3.connect(DATABASE_PATH)
        conn.row_factory = sqlite3.Row
        conn.execute("PRAGMA foreign_keys = ON")
        conn.execute("PRAGMA journal_mode = WAL")
        conn.execute("PRAGMA synchronous = NORMAL")
        g._db_conn = conn
    return conn

@app.teardown_appcontext
def close_db(exc):
    conn = getattr(g, "_db_conn", None)
    if conn is not None:
        try:
            conn.close()
        except Exception:
            pass

def init_db():
    conn = sqlite3.connect(DATABASE_PATH)
    try:
        conn.execute("PRAGMA foreign_keys = ON")
        conn.execute("PRAGMA journal_mode = WAL")
        conn.execute("PRAGMA synchronous = NORMAL")
        conn.execute("""CREATE TABLE IF NOT EXISTS users (
            id INTEGER PRIMARY KEY,
            username TEXT NOT NULL,
            email TEXT NOT NULL UNIQUE,
            password_hash TEXT NOT NULL,
            plan_type TEXT NOT NULL DEFAULT 'starter',
            credits REAL NOT NULL DEFAULT 100.0
        )""")
        conn.execute("""CREATE TABLE IF NOT EXISTS projects (
            id INTEGER PRIMARY KEY,
            owner_id INTEGER NOT NULL,
            name TEXT NOT NULL,
            files_json TEXT NOT NULL DEFAULT '{}',
            visibility TEXT NOT NULL DEFAULT 'private',
            snapshots_json TEXT NOT NULL DEFAULT '[]',
            collaborators_json TEXT NOT NULL DEFAULT '[]',
            FOREIGN KEY(owner_id) REFERENCES users(id) ON DELETE CASCADE
        )""")
        conn.execute("""CREATE TABLE IF NOT EXISTS teams (
            id INTEGER PRIMARY KEY,
            name TEXT NOT NULL,
            admin_id INTEGER NOT NULL,
            members_json TEXT NOT NULL DEFAULT '[]',
            FOREIGN KEY(admin_id) REFERENCES users(id) ON DELETE CASCADE
        )""")
        conn.execute("""CREATE TABLE IF NOT EXISTS billing (
            id INTEGER PRIMARY KEY,
            user_id INTEGER NOT NULL UNIQUE,
            usage_json TEXT NOT NULL DEFAULT '{}',
            invoices_json TEXT NOT NULL DEFAULT '[]',
            FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE
        )""")
        conn.execute("""CREATE TABLE IF NOT EXISTS databases (
            id INTEGER PRIMARY KEY,
            project_id INTEGER NOT NULL UNIQUE,
            schema_json TEXT NOT NULL DEFAULT '{}',
            data_json TEXT NOT NULL DEFAULT '{}',
            FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE
        )""")
        conn.execute("""CREATE TABLE IF NOT EXISTS storage (
            id INTEGER PRIMARY KEY,
            project_id INTEGER NOT NULL UNIQUE,
            files_json TEXT NOT NULL DEFAULT '{}',
            FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE
        )""")
        conn.execute("""CREATE TABLE IF NOT EXISTS ai_conversations (
            id INTEGER PRIMARY KEY,
            project_id INTEGER NOT NULL UNIQUE,
            history_json TEXT NOT NULL DEFAULT '[]',
            FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE
        )""")
        conn.execute("""CREATE TABLE IF NOT EXISTS secrets (
            id INTEGER PRIMARY KEY,
            project_id INTEGER NOT NULL,
            key TEXT NOT NULL,
            value TEXT NOT NULL,
            UNIQUE(project_id, key),
            FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE
        )""")
        conn.commit()
    finally:
        conn.close()

def generate_token(user_id):
    payload = {"user_id": int(user_id), "exp": datetime.now(timezone.utc) + timedelta(hours=JWT_EXP_HOURS)}
    token = jwt.encode(payload, SECRET_KEY, algorithm=JWT_ALGORITHM)
    if isinstance(token, bytes):
        token = token.decode("utf-8")
    return token

def _get_auth_token():
    header = request.headers.get("Authorization", "")
    if not header:
        return None
    parts = header.split()
    if len(parts) == 1:
        return parts[0]
    if len(parts) == 2 and parts[0].lower() == "bearer":
        return parts[1]
    return None

def token_required(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = _get_auth_token()
        if not token:
            return jsonify({"message": "Token is missing"}), 401
        try:
            data = jwt.decode(token, SECRET_KEY, algorithms=[JWT_ALGORITHM])
            current_user = int(data["user_id"])
        except Exception:
            return jsonify({"message": "Token is invalid"}), 401
        return f(current_user, *args, **kwargs)
    return decorated

@app.after_request
def add_cors_headers(resp):
    origin = request.headers.get("Origin")
    allowed = CORS_ALLOWED_ORIGINS
    if allowed == "*":
        resp.headers["Access-Control-Allow-Origin"] = "*"
    elif origin and origin in {o.strip() for o in allowed.split(",") if o.strip()}:
        resp.headers["Access-Control-Allow-Origin"] = origin
    resp.headers["Access-Control-Allow-Headers"] = "Authorization, Content-Type"
    resp.headers["Access-Control-Allow-Methods"] = "GET, POST, PUT, DELETE, OPTIONS"
    return resp

def _require_json():
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return None
    return data

def _require_fields(data, fields):
    for f in fields:
        if f not in data or data[f] is None:
            raise KeyError(f)

def _project_owned(conn, current_user, project_id):
    row = conn.execute("SELECT id FROM projects WHERE id = ? AND owner_id = ?", (project_id, current_user)).fetchone()
    return row is not None

def _get_user_credits(conn, user_id):
    row = conn.execute("SELECT credits FROM users WHERE id = ?", (user_id,)).fetchone()
    if not row:
        return None
    return float(row["credits"])

def _deduct_credits(conn, user_id, amount):
    conn.execute("UPDATE users SET credits = credits - ? WHERE id = ?", (float(amount), int(user_id)))

def _xai_chat(messages, timeout=30):
    if not XAI_API_KEY:
        raise RuntimeError("XAI_API_KEY is not configured")
    headers = {"Authorization": f"Bearer {XAI_API_KEY}", "Content-Type": "application/json"}
    body = {"model": XAI_MODEL, "messages": messages}
    r = requests.post(XAI_CHAT_URL, headers=headers, json=body, timeout=timeout)
    r.raise_for_status()
    j = r.json()
    return j["choices"][0]["message"]["content"]

def _bedrock_chat(user_text, max_tokens=4096, temperature=0.7):
    client = get_bedrock_client()
    payload = {
        "anthropic_version": "bedrock-2023-05-31",
        "max_tokens": int(max_tokens),
        "temperature": float(temperature),
        "messages": [{"role": "user", "content": [{"type": "text", "text": user_text}]}],
    }
    body = json.dumps(payload)
    resp = client.invoke_model(modelId=BEDROCK_MODEL_ID, body=body)
    raw = resp["body"].read()
    out = json.loads(raw)
    return out["content"][0]["text"]

def _ai_agent_core(conn, current_user, prompt, project_id):
    credits = _get_user_credits(conn, current_user)
    if credits is None:
        return jsonify({"message": "User not found"}), 404
    if credits < CREDIT_COST_AGENT:
        return jsonify({"message": "Insufficient credits"}), 402
    if not project_id:
        return jsonify({"message": "project_id is required"}), 400
    project_id = int(project_id)
    if not _project_owned(conn, current_user, project_id):
        return jsonify({"message": "Unauthorized"}), 403
    reasoned_prompt = _xai_chat([
        {"role": "system", "content": "You are a fast reasoning AI for planning code tasks."},
        {"role": "user", "content": str(prompt)},
    ])
    model_text = _bedrock_chat(reasoned_prompt)
    try:
        patch = _extract_json_object(model_text)
    except Exception as e:
        return jsonify({"message": "Model output must be a JSON object mapping filenames to file contents", "error": str(e), "raw": model_text[:2000]}), 502
    for k, v in list(patch.items()):
        if not isinstance(k, str) or not isinstance(v, str):
            return jsonify({"message": "Invalid patch format. Keys and values must be strings."}), 502
    row = conn.execute("SELECT files_json, snapshots_json FROM projects WHERE id = ?", (project_id,)).fetchone()
    if not row:
        return jsonify({"message": "Project not found"}), 404
    files = _json_loads(row["files_json"], {})
    if not isinstance(files, dict):
        files = {}
    files.update(patch)
    snapshots = _json_loads(row["snapshots_json"], [])
    if not isinstance(snapshots, list):
        snapshots = []
    snapshots.append({"timestamp": time.time(), "user_id": int(current_user), "files": files})
    conn.execute("UPDATE projects SET files_json = ?, snapshots_json = ? WHERE id = ?", (json.dumps(files, ensure_ascii=False), json.dumps(snapshots, ensure_ascii=False), project_id))
    _deduct_credits(conn, current_user, CREDIT_COST_AGENT)
    conn.commit()
    return jsonify({"output": model_text, "applied": list(patch.keys())})

def _ai_assistant_core(conn, current_user, mode, prompt, project_id=None):
    credits = _get_user_credits(conn, current_user)
    if credits is None:
        return jsonify({"message": "User not found"}), 404
    if mode == "basic":
        cost = CREDIT_COST_ASSISTANT_BASIC
        if credits < cost:
            return jsonify({"message": "Insufficient credits"}), 402
        output = _bedrock_chat(str(prompt))
        _deduct_credits(conn, current_user, cost)
        conn.commit()
        return jsonify({"response": output})
    if mode == "advanced":
        cost = CREDIT_COST_ASSISTANT_ADVANCED
        if credits < cost:
            return jsonify({"message": "Insufficient credits"}), 402
        reasoned = _xai_chat([
            {"role": "system", "content": "You are a fast reasoning AI."},
            {"role": "user", "content": str(prompt)},
        ])
        output = _bedrock_chat(reasoned)
        if project_id is not None:
            project_id = int(project_id)
            if not _project_owned(conn, current_user, project_id):
                return jsonify({"message": "Unauthorized"}), 403
            try:
                patch = _extract_json_object(output)
                if isinstance(patch, dict):
                    row = conn.execute("SELECT files_json FROM projects WHERE id = ?", (project_id,)).fetchone()
                    if row:
                        files = _json_loads(row["files_json"], {})
                        if not isinstance(files, dict):
                            files = {}
                        for k, v in patch.items():
                            if isinstance(k, str) and isinstance(v, str):
                                files[k] = v
                        conn.execute("UPDATE projects SET files_json = ? WHERE id = ?", (json.dumps(files, ensure_ascii=False), project_id))
            except Exception:
                pass
        _deduct_credits(conn, current_user, cost)
        conn.commit()
        return jsonify({"response": output})
    return jsonify({"message": "Invalid mode"}), 400

@app.route("/register", methods=["POST"])
def register():
    data = _require_json()
    if data is None:
        return jsonify({"message": "Invalid JSON"}), 400
    try:
        _require_fields(data, ["username", "email", "password"])
    except KeyError as e:
        return jsonify({"message": f"Missing field: {e.args[0]}"}), 400
    username = str(data["username"]).strip()
    email = str(data["email"]).strip().lower()
    password = str(data["password"])
    if not username or not email or not password:
        return jsonify({"message": "username, email and password are required"}), 400
    password_hash = bcrypt.hashpw(password.encode("utf-8"), bcrypt.gensalt()).decode("utf-8")
    conn = get_db()
    try:
        cur = conn.execute("INSERT INTO users (username, email, password_hash) VALUES (?, ?, ?)", (username, email, password_hash))
        user_id = cur.lastrowid
        conn.execute("INSERT INTO billing (user_id) VALUES (?)", (user_id,))
        conn.commit()
    except sqlite3.IntegrityError:
        conn.rollback()
        return jsonify({"message": "Email already registered"}), 409
    token = generate_token(user_id)
    return jsonify({"token": token})

