@app.route("/sso", methods=["POST"])
def sso():
    data = _require_json()
    if data is None:
        return jsonify({"message": "Invalid JSON"}), 400
    email = data.get("email")
    if not email:
        return jsonify({"message": "Invalid SSO data"}), 400
    email = str(email).strip().lower()
    username = email.split("@", 1)[0] if "@" in email else email
    conn = get_db()
    user = conn.execute("SELECT id FROM users WHERE email = ?", (email,)).fetchone()
    if user:
        token = generate_token(user["id"])
        return jsonify({"token": token})
    password_hash = bcrypt.hashpw(os.urandom(32), bcrypt.gensalt()).decode("utf-8")
    try:
        cur = conn.execute("INSERT INTO users (username, email, password_hash, plan_type, credits) VALUES (?, ?, ?, ?, ?)", (username, email, password_hash, "enterprise", 5000.0))
        user_id = cur.lastrowid
        conn.execute("INSERT INTO billing (user_id) VALUES (?)", (user_id,))
        conn.commit()
    except sqlite3.IntegrityError:
        conn.rollback()
        user = conn.execute("SELECT id FROM users WHERE email = ?", (email,)).fetchone()
        if not user:
            return jsonify({"message": "SSO failed"}), 500
        user_id = user["id"]
    token = generate_token(user_id)
    return jsonify({"token": token})

