@app.route("/projects/<int:project_id>", methods=["PUT"])
@token_required
def update_project(current_user, project_id):
    data = _require_json()
    if data is None:
        return jsonify({"message": "Invalid JSON"}), 400
    conn = get_db()
    if not _project_owned(conn, current_user, project_id):
        return jsonify({"message": "Not found"}), 404
    name = data.get("name")
    files_json = data.get("files_json")
    visibility = data.get("visibility")
    row = conn.execute("SELECT name, files_json, visibility FROM projects WHERE id = ?", (project_id,)).fetchone()
    new_name = str(name).strip() if name is not None else row["name"]
    new_files = files_json if files_json is not None else _json_loads(row["files_json"], {})
    if not isinstance(new_files, dict):
        return jsonify({"message": "files_json must be an object"}), 400
    new_visibility = str(visibility) if visibility is not None else row["visibility"]
    if new_visibility not in {"private", "public"}:
        return jsonify({"message": "visibility must be private or public"}), 400
    conn.execute("UPDATE projects SET name = ?, files_json = ?, visibility = ? WHERE id = ?", (new_name, json.dumps(new_files, ensure_ascii=False), new_visibility, project_id))
    conn.commit()
    return jsonify({"message": "Updated"})

