@app.route("/import", methods=["POST"])
@token_required
def import_project(current_user):
    data = _require_json()
    if data is None:
        return jsonify({"message": "Invalid JSON"}), 400
    source = str(data.get("source", "")).strip()
    if not source:
        return jsonify({"message": "source is required"}), 400
    name = str(data.get("name", "Imported Project")).strip() or "Imported Project"
    files = {}
    if source.lower().endswith(".zip"):
        r = requests.get(source, timeout=60)
        r.raise_for_status()
        content = r.content
        if len(content) > app.config["MAX_CONTENT_LENGTH"]:
            return jsonify({"message": "ZIP too large"}), 413
        with zipfile.ZipFile(io.BytesIO(content)) as z:
            for fname in z.namelist():
                if fname.endswith("/"):
                    continue
                with z.open(fname) as f:
                    b = f.read()
                try:
                    files[fname] = b.decode("utf-8")
                except UnicodeDecodeError:
                    files[fname] = base64.b64encode(b).decode("ascii")
    else:
        return jsonify({"message": "Only .zip sources are supported"}), 400
    conn = get_db()
    cur = conn.execute("INSERT INTO projects (owner_id, name, files_json) VALUES (?, ?, ?)", (current_user, name, json.dumps(files, ensure_ascii=False)))
    project_id = cur.lastrowid
    conn.execute("INSERT OR IGNORE INTO databases (project_id) VALUES (?)", (project_id,))
    conn.execute("INSERT OR IGNORE INTO storage (project_id) VALUES (?)", (project_id,))
    conn.execute("INSERT OR IGNORE INTO ai_conversations (project_id) VALUES (?)", (project_id,))
    conn.commit()
    return jsonify({"project_id": project_id, "files": list(files.keys())})

@app.route("/join/<link>", methods=["GET"])
@token_required
def join_project(current_user, link):
    try:
        project_id = int(_urlsafe_b64decode_padded(link).decode("utf-8"))
    except Exception:
        return jsonify({"message": "Invalid link"}), 400
    conn = get_db()
    row = conn.execute("SELECT owner_id, collaborators_json FROM projects WHERE id = ?", (project_id,)).fetchone()
    if not row:
        return jsonify({"message": "Not found"}), 404
    if int(row["owner_id"]) == int(current_user):
        return jsonify({"message": "Already owner"})
    collaborators = _json_loads(row["collaborators_json"], [])
    if not isinstance(collaborators, list):
        collaborators = []
    if int(current_user) not in [int(x) for x in collaborators if isinstance(x, (int, float, str)) and str(x).isdigit()]:
        collaborators.append(int(current_user))
        conn.execute("UPDATE projects SET collaborators_json = ? WHERE id = ?", (json.dumps(collaborators), project_id))
        conn.commit()
    return jsonify({"message": "Joined", "project_id": project_id})

