    conn.commit()
    return jsonify({"message": "Secret saved"})

@app.route("/version_control/<int:project_id>", methods=["GET", "POST"])
@token_required
def version_control(current_user, project_id):
    conn = get_db()
    if not _project_owned(conn, current_user, project_id):
        return jsonify({"message": "Not found"}), 404
    if request.method == "GET":
        row = conn.execute("SELECT snapshots_json FROM projects WHERE id = ?", (project_id,)).fetchone()
        snapshots = _json_loads(row["snapshots_json"], []) if row else []
        if not isinstance(snapshots, list):
            snapshots = []
        return jsonify({"history": snapshots})
    data = _require_json()
    if data is None:
        return jsonify({"message": "Invalid JSON"}), 400
    snapshot = data.get("snapshot")
    if not isinstance(snapshot, dict):
        return jsonify({"message": "snapshot must be an object"}), 400
    row = conn.execute("SELECT snapshots_json FROM projects WHERE id = ?", (project_id,)).fetchone()
    snapshots = _json_loads(row["snapshots_json"], []) if row else []
    if not isinstance(snapshots, list):
        snapshots = []
    snapshot.setdefault("timestamp", time.time())
    snapshot.setdefault("user_id", int(current_user))
    snapshots.append(snapshot)
    conn.execute("UPDATE projects SET snapshots_json = ? WHERE id = ?", (json.dumps(snapshots, ensure_ascii=False), project_id))
    conn.commit()
    return jsonify({"message": "Committed"})

