@app.route("/db/<int:project_id>", methods=["POST", "GET", "PUT"])
@token_required
def db_manage(current_user, project_id):
    conn = get_db()
    if not _project_owned(conn, current_user, project_id):
        return jsonify({"message": "Not found"}), 404
    entry = conn.execute("SELECT schema_json, data_json FROM databases WHERE project_id = ?", (project_id,)).fetchone()
    if not entry:
        conn.execute("INSERT OR IGNORE INTO databases (project_id) VALUES (?)", (project_id,))
        conn.commit()
        entry = conn.execute("SELECT schema_json, data_json FROM databases WHERE project_id = ?", (project_id,)).fetchone()
    if request.method == "GET":
        return jsonify({"schema": _json_loads(entry["schema_json"], {}), "data": _json_loads(entry["data_json"], {})})
    data = _require_json()
    if data is None:
        return jsonify({"message": "Invalid JSON"}), 400
    if request.method == "POST":
        schema = data.get("schema")
        if not isinstance(schema, dict):
            return jsonify({"message": "schema must be an object"}), 400
        conn.execute("UPDATE databases SET schema_json = ? WHERE project_id = ?", (json.dumps(schema, ensure_ascii=False), project_id))
    elif request.method == "PUT":
        d = data.get("data")
        if not isinstance(d, (dict, list)):
            return jsonify({"message": "data must be an object or array"}), 400
        conn.execute("UPDATE databases SET data_json = ? WHERE project_id = ?", (json.dumps(d, ensure_ascii=False), project_id))
    conn.commit()
    return jsonify({"message": "Updated"})

@app.route("/storage/<int:project_id>", methods=["POST", "GET"])
@token_required
def storage_manage(current_user, project_id):
    conn = get_db()
    if not _project_owned(conn, current_user, project_id):
        return jsonify({"message": "Not found"}), 404
    row = conn.execute("SELECT files_json FROM storage WHERE project_id = ?", (project_id,)).fetchone()
    if not row:
        conn.execute("INSERT OR IGNORE INTO storage (project_id) VALUES (?)", (project_id,))
        conn.commit()
        row = conn.execute("SELECT files_json FROM storage WHERE project_id = ?", (project_id,)).fetchone()
    files = _json_loads(row["files_json"], {})
    if not isinstance(files, dict):
        files = {}
    if request.method == "GET":
        file_name = request.args.get("file")
        if file_name:
            content = files.get(file_name)
            if content is None:
                return jsonify({"message": "Not found"}), 404
            return jsonify({"file": file_name, "content_base64": content})
        return jsonify({"files": list(files.keys())})
    if "file" not in request.files:
        return jsonify({"message": "file is required"}), 400
    f = request.files["file"]
    if not f.filename:
        return jsonify({"message": "filename is required"}), 400
    file_name = secure_filename(f.filename)
    b = f.read()
    files[file_name] = base64.b64encode(b).decode("ascii")
    conn.execute("UPDATE storage SET files_json = ? WHERE project_id = ?", (json.dumps(files), project_id))
    conn.commit()
    return jsonify({"message": "Uploaded", "file": file_name})

