@token_required
def team_members(current_user, team_id):
    conn = get_db()
    team = conn.execute("SELECT id, admin_id, members_json FROM teams WHERE id = ?", (team_id,)).fetchone()
    if not team:
        return jsonify({"message": "Not found"}), 404
    if int(team["admin_id"]) != int(current_user):
        return jsonify({"message": "Unauthorized"}), 403
    members = _json_loads(team["members_json"], [])
    if not isinstance(members, list):
        members = []
    if request.method == "GET":
        return jsonify({"members": members})
    data = _require_json()
    if data is None:
        return jsonify({"message": "Invalid JSON"}), 400
    user_id = data.get("user_id")
    if user_id is None or not str(user_id).isdigit():
        return jsonify({"message": "user_id is required"}), 400
    user_id = int(user_id)
    if user_id not in [int(x) for x in members if isinstance(x, (int, float, str)) and str(x).isdigit()]:
        members.append(user_id)
        conn.execute("UPDATE teams SET members_json = ? WHERE id = ?", (json.dumps(members), team_id))
        conn.commit()
    return jsonify({"message": "Added"})

